        } finally { $lock = get_option(self::LOCK); if (is_array($lock) && ($lock['id'] ?? null) === $id && ($lock['owner'] ?? 0) === get_current_user_id()) { delete_option(self::LOCK); } }
    }
    public static function forget($id) { if (!self::authorize()) { return self::error('Administrator permission required.'); } return self::locked(function() use ($id) { return self::delete_record($id); }); }
    private static function delete_record($id) { $record = self::load($id); if (is_wp_error($record)) { return $record; } $lock = get_option(self::LOCK); if (is_array($lock) && ($lock['id'] ?? '') === $id) { return self::error('Cannot forget a locked recovery record.'); } delete_option(self::PREFIX . $id); if (get_option(self::PREFIX . $id, false) !== false) { return self::error('Could not remove the private record.'); } update_user_meta(get_current_user_id(), '_alify_cf_migrations', array_values(array_diff(self::ids(), array($id)))); return true; }
    public static function boot() {
        add_action('admin_menu', function() { add_submenu_page('edit.php?post_type=' . Alify_CF::GROUP, 'Migrations & ACF Import', 'Migrations & ACF Import', 'manage_options', 'alify-migrations', array(__CLASS__, 'page')); }); add_action('admin_post_alify_migration', array(__CLASS__, 'handle'));
    }
    public static function page() {
        if (!self::authorize()) { wp_die('Administrator permission required.'); }
        echo '<div class="wrap"><h1>Migrations &amp; ACF Schema Import</h1><p>Explicit existing-post migrations only. Define source and destination fields first. No schema rename, source deletion, automatic whole-site scan or automatic schema changes. ACF content plans copy only explicitly declared metadata and ID mappings. Back up the database before applying. At most 100 posts / 20 mappings / 1 MiB per plan; ten private records per administrator.</p><h2>Dry-run migration</h2><form method="post" action="' . esc_url(admin_url('admin-post.php')) . '"><input type="hidden" name="action" value="alify_migration"><input type="hidden" name="operation" value="plan">'; wp_nonce_field('alify_migration_plan'); echo '<textarea class="large-text code" rows="8" name="json" aria-label="Migration specification">' . esc_textarea('{"posts":[123],"mappings":[{"from":"old_name","to":"new_name","mode":"copy"}],"overwrite":false}') . '</textarea><button class="button button-primary">Create validated plan (no content writes)</button></form><h2>Your private plans/backups</h2>';
        foreach (self::ids() as $id) { $summary = self::summary($id); if (is_wp_error($summary)) { continue; } echo '<p>' . esc_html($summary['kind'] . ' — ' . $id . ' — ' . $summary['status'] . ' — ' . $summary['posts'] . ' posts / ' . $summary['mappings'] . ' mappings') . '</p>'; foreach (array('apply' => 'Apply', 'rollback' => 'Rollback', 'forget' => 'Forget backup') as $operation => $label) { echo '<form style="display:inline-block;margin-right:8px" method="post" action="' . esc_url(admin_url('admin-post.php')) . '"><input type="hidden" name="action" value="alify_migration"><input type="hidden" name="operation" value="' . esc_attr($operation) . '"><input type="hidden" name="id" value="' . esc_attr($id) . '">'; wp_nonce_field('alify_migration_' . $operation . '_' . $id); echo '<button class="button">' . esc_html($label) . '</button></form>'; } }
        echo '<h2>ACF content migration (separate from schema import)</h2><p>Existing database/post IDs only. Publish destination fields first. Declare exact ACF field keys/types and map every media/reference ID, including same-site identity mappings. All destination Group/Repeater children must be declared; undeclared source data stays unmigrated. No source deletion, file copying, term assignment or automatic compatibility.</p><form method="post" action="' . esc_url(admin_url('admin-post.php')) . '"><input type="hidden" name="action" value="alify_migration"><input type="hidden" name="operation" value="plan_acf">'; wp_nonce_field('alify_migration_plan_acf'); echo '<textarea class="large-text code" rows="8" name="json" aria-label="ACF content migration specification">' . esc_textarea('{"posts":[123],"mappings":[{"from":"legacy_name","to":"new_name","acf":{"key":"field_legacy_key","type":"text"}}],"overwrite":false}') . '</textarea><button class="button">Plan ACF content migration (no content writes)</button></form>';
        echo '<h2>ACF schema-only import</h2><p>One group at a time. Supported basic/choice fields and single-level Group/Repeater; unsupported types/settings/conditions reject the entire import. Source content, references, credentials and callbacks are never read. Inspect first; warnings describe intentional differences.</p><form method="post" action="' . esc_url(admin_url('admin-post.php')) . '"><input type="hidden" name="action" value="alify_migration">'; wp_nonce_field('alify_migration_acf'); echo '<textarea class="large-text code" rows="10" name="json" aria-label="ACF schema JSON"></textarea><button name="operation" value="inspect_acf" class="button">Inspect schema</button> <button name="operation" value="import_acf" class="button button-primary">Import as new draft</button></form></div>';
    }
    public static function handle() {
        if (!self::authorize()) { wp_die('Administrator permission required.', '', array('response' => 403)); } $request = wp_unslash($_POST); $operation = $request['operation'] ?? ''; $id = $request['id'] ?? '';
        if (!is_string($operation) || !is_string($id) || !in_array($operation, array('plan', 'apply', 'rollback', 'forget', 'inspect_acf', 'import_acf', 'plan_acf'), true)) { wp_die('Invalid operation.', '', array('response' => 400)); }
        check_admin_referer(in_array($operation, array('inspect_acf', 'import_acf'), true) ? 'alify_migration_acf' : ('alify_migration_' . $operation . (in_array($operation, array('apply', 'rollback', 'forget'), true) ? '_' . $id : '')));
        if ($operation === 'plan' || $operation === 'plan_acf') { $raw = is_string($request['json'] ?? null) && strlen($request['json']) <= 1048576 ? json_decode($request['json'], true, 16) : null; $result = is_array($raw) && !array_diff(array_keys($raw), array('posts', 'mappings', 'overwrite')) ? ($operation === 'plan_acf' ? self::plan_acf($raw['posts'] ?? null, $raw['mappings'] ?? null, $raw['overwrite'] ?? false) : self::plan($raw['posts'] ?? null, $raw['mappings'] ?? null, $raw['overwrite'] ?? false)) : self::error('Invalid bounded migration JSON.'); }
        elseif ($operation === 'inspect_acf' || $operation === 'import_acf') {
            $result = $operation === 'inspect_acf' ? Alify_CF_ACF_Import::inspect($request['json'] ?? null) : Alify_CF_ACF_Import::import($request['json'] ?? null);
            if (!is_wp_error($result)) { $report = $operation === 'inspect_acf' ? array('valid' => $result['valid'], 'errors' => $result['errors'], 'warnings' => $result['warnings']) : $result; wp_die('<pre>' . esc_html(wp_json_encode($report, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)) . '</pre>', 'Schema report', array('response' => 200, 'back_link' => true)); }
        } elseif ($operation === 'forget') { $result = self::forget($id); } else { $result = self::execute($id, $operation === 'rollback'); }
        if (is_wp_error($result)) { wp_die(esc_html($result->get_error_message()), 'Migration not completed', array('response' => 400, 'back_link' => true)); } wp_safe_redirect(admin_url('edit.php?post_type=' . Alify_CF::GROUP . '&page=alify-migrations')); exit;
    }
}
